INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('West Cork’s domestic violence service publishes unique newsletter', 'west-corks-domestic-violence-service-publishes-unique-newsletter', '<p>They are to be complimented on reaching their 80th edition &#8211; check it out &#8211; subscription details below (it’s free).<br />
In the meantime, Maria Mulholland, co-ordinator of WCWAV, said she is glad to see that domestic violence has become a government priority and she hopes to see the opening of more domestic violence emergency accommodation.<br />
“There was one major benefit from Covid for the domestic violence sector. It exposed the dearth of refuges and safe housing spaces available to victims,” she said.<br />
“Covid highlighted that the old-style, communal refuges are no longer fit for purpose as these were unable to take their normal numbers because of Covid, reducing already scarce places in refuges by 50%.”<br />
The scarcity of emergency accommodation was recently highlighted by Tusla.</p>
<h2>Refuges now a priority</h2>
<figure aria-describedby="caption-attachment-251813"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2022/05/Marie-Mulholland-HS.jpg" alt="" width="736" height="529" srcset="https://changingireland.ie/wp-content/uploads/2022/05/Marie-Mulholland-HS.jpg 736w, https://changingireland.ie/wp-content/uploads/2022/05/Marie-Mulholland-HS-300x216.jpg 300w" sizes="(max-width: 736px) 100vw, 736px" /><figcaption><em>• Marie Mulholland.</em></figcaption></figure>
<p>Mulholland said, “A recent accommodation review of domestic violence spaces conducted by Tusla identified that at least 60 new units of accommodation are required in 10 locations across Ireland, including in Cork and West Cork. These areas are now a priority.”<br />
In February, the Department of Justice published and sought the public’s views on a new National Strategy on Domestic, Sexual and Gender-based Violence. Mulholland hopes that this third national strategy will lead to “radical change in prevention, protection, prosecution and policy areas”.</p>
<h2>Lucky break</h2>
<p>So, how did the projects such as WCWAV handle the increase in demand during Covid? They adjusted like other frontline community groups.<br />
In West Cork they also got a lucky break.<br />
Mulholland said: &#8220;We worked remotely, while ensuring we were always on the end of a phone for anyone who called. We placed ads in local press and media to let those who needed us know that the service was still operating and that we were still here for them.<br />
“We worked closely with our local Garda division to devise a process and protocols for transporting women and children to safety.<br />
“Very importantly, we were given the use of holiday homes by owners who lived outside West Cork – for use by those most in need of emergency accommodation due to domestic violence.<br />
“During the lockdowns, we worked longer hours and if truth be told we are still dealing with the aftermath of the increase in domestic abuse due to Covid and lockdown restrictions,” she said.</p>
<p>Subscribe to Their Newsletter For a copy of the West Cork Whisper, email: admin@westcorkwomensproject.ie<br />
Alternatively, you can subscribe via this link:<br />
<a href="https://bit.ly/WestCorkWhisperSub2022">https://bit.ly/WestCorkWhisperSub2022</a></p>
<p>Follow them Online<br />
WCWAV is active on Twitter and Facebook. Their website is:<br />
<a href="https://www.westcorkwomensproject.ie/">www.westcorkwomensproject.ie</a></p>
<blockquote><p><a href="https://changingireland.ie/domestic-violence-offaly-support-workers-get-calls-from-around-the-world/">DOMESTIC VIOLENCE: Offaly support workers get calls from around the world</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“DOMESTIC VIOLENCE: Offaly support workers get calls from around the world” — Changing Ireland" src="https://changingireland.ie/domestic-violence-offaly-support-workers-get-calls-from-around-the-world/embed/#?secret=ZPeX6sQQ7K#?secret=uhhoDduHvd" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Recently, West Cork Women Against Violence (WCWAV) published the 80th edition of their ‘West Cork Whisper’ newsletter. It is immensely practical, thoughtful and clearly laid out and the publication is useful to any and all working / volunteering in the domestic violence sector – no matter where in Ireland you are. This is not only because the ‘West Cork Whisper’ is the only one of its kind published in the country, but because of the quality of the content.', 'https://changingireland.ie/wp-content/uploads/2022/05/Photo-courtesy-of-the-West-Cork-Whistle-e1652194837536.png', '', '[{"slug":"health","title":"Health"}]', '[{"slug":"cork","title":"Cork"},{"slug":"domestic-violence","title":"Domestic Violence"}]', '', 251828, 1, '2022-05-11T13:13:56Z', '2022-05-11T13:23:51Z', '2022-05-11T13:13:56Z')
