INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€1 million in Capital Funding for Social Enterprises', 'e1-million-in-capital-funding-for-social-enterprises', '<p>The grants range from a few hundred euro to €14,500 and are being provided through the new Social Enterprises Capital Grants Scheme.</p>
<p>To take three: Happy Day Child-care Services in Co. Cavan is to receive €3,000 towards a new kitchen, Revive New Ross is getting €7,500 in foodbank equipment and Pallasgreen Templebraden Community Council is getting €940 to repair a floor.</p>
<p>Organisations were not short of ideas, with applications received and approved for alarm installation (Fenagh Development Company in Co. Tipperary), new gates (Listry Community Council in Co. Kerry), therapy room facilities (the Urban Co-op in Limerick) and the refurbishment of playground refurbishment (Killucan Community Centre in Co. Westmeath).</p>
<p>“The grants may be small in nature but I know they will greatly assist Social Enterprises the length and breadth of the country who have continued to serve their communities through the pandemic,” said Heather Humprheys, Minister for Rural and Community Development.</p>
<figure aria-describedby="caption-attachment-251366"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/12/Minister-Humphreys-in-Templemore-Town-Park.png" alt="" width="1603" height="900" srcset="https://changingireland.ie/wp-content/uploads/2021/12/Minister-Humphreys-in-Templemore-Town-Park.png 1603w, https://changingireland.ie/wp-content/uploads/2021/12/Minister-Humphreys-in-Templemore-Town-Park-300x168.png 300w, https://changingireland.ie/wp-content/uploads/2021/12/Minister-Humphreys-in-Templemore-Town-Park-1024x575.png 1024w, https://changingireland.ie/wp-content/uploads/2021/12/Minister-Humphreys-in-Templemore-Town-Park-768x431.png 768w, https://changingireland.ie/wp-content/uploads/2021/12/Minister-Humphreys-in-Templemore-Town-Park-1536x862.png 1536w, https://changingireland.ie/wp-content/uploads/2021/12/Minister-Humphreys-in-Templemore-Town-Park-1080x606.png 1080w" sizes="(max-width: 1603px) 100vw, 1603px" /><figcaption><em>• Minister Heather Humphreys in Templemore Town Park recently.</em></figcaption></figure>
<p>The scheme she announced today was committed to in the State’s first National Social Enterprise Strategy launched in mid-2019. It also supports the objectives of the Government’s five-year ‘Our Rural Future’ strategy.</p>
<p>The Social Enterprises Capital Grants Scheme is funded through the Dormant Accounts Fund and the grants will be administered on behalf of the Department by the Local Community Development Committees (LCDCs).</p>
<p>More details available in the Department press statement issued this morning &#8211; <a href="https://www.gov.ie/en/press-release/3e318-minister-humphreys-announces-1-million-in-capital-funding-for-social-enterprises/">https://www.gov.ie/en/press-release/3e318-minister-humphreys-announces-1-million-in-capital-funding-for-social-enterprises/</a></p>
<p>&nbsp;</p>
<p>A list of the benefitting organisations can be downloaded here: <a href="https://www.gov.ie/en/collection/56dc6-social-enterprise-small-capital-grants-scheme-2021/">https://www.gov.ie/en/collection/56dc6-social-enterprise-small-capital-grants-scheme-2021/</a></p>
<p>&nbsp;</p>
<p><strong>Background: </strong></p>
<p>Ireland’s first National Social Enterprise Policy for Ireland 2019-2022 was launched by the Department of Rural and Community Development in July 2019, with the objective of creating an enabling environment for social enterprise to grow and contribute more fully to Ireland’s social and economic progress.</p>
<p>The Policy is focused on three main objectives:</p>
<ol>
<li>Building Awareness of Social Enterprise</li>
<li>Growing and Strengthening Social Enterprise</li>
<li>Achieving Better Policy Alignment</li>
</ol>', '247 organisations were approved today to share €1m from the new Social Enterprises Capital Grants Scheme. The funds will be spent on everything from swimming pools to childcare to community centres and foodbank centres.', 'https://changingireland.ie/wp-content/uploads/2021/12/Happy-Days-childcare-Co-Cavan.jpg', '', '[{"slug":"funding","title":"Funding"},{"slug":"grants-subsidies","title":"Grants & Subsidies"}]', '[{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"social-enterprise","title":"social enterprise"},{"slug":"social-enterprises-capital-grants-schemeital-grants-scheme","title":"Social Enterprises Capital Grants Schemeital Grants Scheme"}]', '', 251359, 1, '2021-12-06T13:17:28Z', '2021-12-06T23:36:50Z', '2021-12-06T13:17:28Z')
