INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('First specialist recruitment company for refugees and asylum-seekers', 'first-specialist-recruitment-company-for-refugees-and-asylum-seekers', '<p align="left"><span lang="EN-GB">Roos Demol is the founder of RecruitRefugees. She has been working with migrants, refugees and asylum seekers since 2014 and wants to tackle the negative stereotypes that exist around refugees and asylum seekers and highlight the huge wealth of talent and skills that they possess. </span></p>
<p align="left"><span lang="EN-GB">Roos celebrates events such as the one held over the summer when over four thousand people who recently received Irish citizenship logged on to attend a virtual celebration which was live streamed from Croke Park.</span></p>
<p align="left"><span lang="EN-GB">She sees these as wonderful events and hopes that “they will also be treated like Irish citizens by employers and be given exactly the same chances as other citizens. It’s what is needed to make the country a place of sanctuary and welcome for everyone.” </span></p>
<p align="left"><span lang="EN-GB">She set up RecruitRefugees (https://recruitrefugees.ie/) as a Cork based social enterprise over a year ago to support refugees and asylum seekers in obtaining employment. </span></p>
<p align="left"><span lang="EN-GB">It calls itself “the first specialist recruitment consultancy and agency for Refugees, Asylum Seekers and Migrants in Ireland”. </span></p>
<p align="left"><span lang="EN-GB">Its mission is to “inspire dignity, hope and a bright future for asylum seekers and refugees in Ireland by connecting people to careers.”</span></p>
<h2>Roos&#8217;s Own Experience</h2>
<p align="left"><span lang="EN-GB">Roos’ own experience as a newcomer to Ireland and former nurse within the prison system in her home country of Belgium has greatly informed her passion for this particular cause. </span></p>
<p align="left"><span lang="EN-GB">She moved to Cork with her husband in 1998 while pregnant with her first child. </span></p>
<p align="left"><span lang="EN-GB">She initially blogged about her experiences trying to get to grips with the Irish healthcare system. However, she became “fed up” with blogging about herself and through a chance encounter, ended up becoming the host of a radio programme for asylum seekers and refugees. </span></p>
<p align="left"><span lang="EN-GB">Other opportunities came along in the form of a music band which showcased the talents of refugees and asylum seekers and enjoyed moderate success, even playing a concert in the National Concert Hall in Dublin! </span></p>
<p align="left"><span lang="EN-GB">She then began volunteering with refugees in a Direct Provision centre, supplying food and clothing and getting to know many personally. </span></p>
<p align="left"><span lang="EN-GB">A one minute “elevator pitch” and a chat at a networking event led to the set-up of Recruit Refugees.ie and she hasn’t looked back since.</span></p>
<h2><span lang="EN-GB">Partner Organisations<br />
</span></h2>
<p align="left"><span lang="EN-GB">RecruitRefugees.ie partners with other organisations: Doras, the Irish Refugee Council, Open Doors, An Cosán, Cork City of Sanctuary, Mukisa, West Cork Development Partnership, MASI, and Sanctuary Runners.</span></p>
<blockquote><p><a href="https://changingireland.ie/egyptian-journalist-free-to-practise-again/">Egyptian journalist free to practise again</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Egyptian journalist free to practise again” — Changing Ireland" src="https://changingireland.ie/egyptian-journalist-free-to-practise-again/embed/#?secret=A65sxoezGn#?secret=p2LhHSYOCr" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/zimbabwean-tech-whiz-calls-for-more-opportunities/">Zimbabwean tech whiz calls for more opportunities</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Zimbabwean tech whiz calls for more opportunities” — Changing Ireland" src="https://changingireland.ie/zimbabwean-tech-whiz-calls-for-more-opportunities/embed/#?secret=RdvwaQnOAT#?secret=u1SvLjEh3Y" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/algerian-volunteer-wants-more-work-while-embracing-diverse-society/">Algerian volunteer wants more work while embracing “diverse society”</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Algerian volunteer wants more work while embracing “diverse society”” — Changing Ireland" src="https://changingireland.ie/algerian-volunteer-wants-more-work-while-embracing-diverse-society/embed/#?secret=Hxl3pjqP73#?secret=UOAIQ5JMNV" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<h2>Pledges on Direct Provision in the Programme for Government</h2>
<p>Asylum-seekers are among the most vulnerable groups in society and the Programme for Government included a pledge to replace the Direct Provision accommodation system and replace it with a new not-for-profit approach with human rights at its core. This work is underway.</p>
<p>The PfG stated: “We are committed to ensuring that Ireland provides protection to those seeking refuge from conflict and persecution, as is required under international law.”</p>
<p>The PfG also pledged to improve conditions in the short term: “This includes vulnerability assessments, the right to work, the ability to apply for driver licences and bank accounts, an independent inspection process, measures to reduce the length of time in processing decisions, mental health services, and the training of managers of Direct Provision Centres.”</p>
<p>The acceptance in the PfG that DP must be replaced by a more humane, non-profit-driven system was seen as a win for activists who campaigned for dignified treatment of refugees and asylum-seekers.</p>', '– RecruitRefugees challenges stereotypes and supports refugees to get work.', 'https://changingireland.ie/wp-content/uploads/2021/11/Photo-of-Roos-Demol-with-Norbert-Nkengurutse-and-Albert-Hakizimana.jpg', '', '[{"slug":"empowerment","title":"Empowerment"},{"slug":"income-employment","title":"Income & Employment"}]', '[{"slug":"refugees","title":"refugees"}]', '', 251240, 1, '2021-11-04T11:08:08Z', '2021-11-04T17:23:14Z', '2021-11-04T11:08:08Z')
