INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Algerian volunteer wants more work while embracing “diverse society”', 'algerian-volunteer-wants-more-work-while-embracing-diverse-society', '<p>Hanane (who asked us not to reveal her surname) is a former asylum seeker from Algeria who came to Ireland in 2015 with her young son. She volunteers with Recruitrefugees.ie in an outreach capacity.</p>
<p>As she is an Arabic and French speaker, she facilitates workshops in Arabic, helps with translation of documents and supports other refugees and asylum seekers to obtain work suited to their qualifications and level of job readiness. She also volunteers with Waterford Integration Services in conjunction with Waterford Youth Services. She previously worked with Waterford Education Centre and Treo on a youth diversion project and is currently studying towards a degree in Community Development and Education ‘ at Waterford IT.</p>
<p>Life in Ireland has also been challenging for her, particularly because of legislation that denied asylum seekers and refugees the right to work and education (a situation that has improved recently). She refers to it as her “journey from oppression to liberation”.</p>
<p>She said the Irish state paid lip service to the idea of integration while placing barriers such as employment restrictions and the prohibition on obtaining a driving licence in the way thereby “increasing the level of stereotyping” and stigmatising of people who live in the DP system.</p>
<p>She emphasises that asylum seekers want to work and believes that “a diverse society is something amazing. Our uniqueness is our difference, I have something that you don’t have and you have something that I don’t have.”</p>
<blockquote><p><a href="https://changingireland.ie/first-specialist-recruitment-company-for-refugees-and-asylum-seekers/">First specialist recruitment company for refugees and asylum-seekers</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“First specialist recruitment company for refugees and asylum-seekers” — Changing Ireland" src="https://changingireland.ie/first-specialist-recruitment-company-for-refugees-and-asylum-seekers/embed/#?secret=Vbj7eEWZEl#?secret=cHbXyS0iCY" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'The prohibition on obtaining a driving licence increases the level of stereotyping and stigmatisation.', 'https://changingireland.ie/wp-content/uploads/2021/11/Driving-license-Edited-4-copy.jpg', '', '[{"slug":"empowerment","title":"Empowerment"},{"slug":"income-employment","title":"Income & Employment"}]', '[{"slug":"refugees","title":"refugees"}]', '', 251252, 1, '2021-11-04T10:50:31Z', '2021-11-04T10:51:20Z', '2021-11-04T10:50:31Z')
