INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Zimbabwean tech whiz calls for more opportunities', 'zimbabwean-tech-whiz-calls-for-more-opportunities', '<p>Andile Mondela from Zimbabwe is another success story. He has a background in hardware and systems administration and has lived in Ireland over four years. Though still in DP, he is busy volunteering as IT manager with RecruitRefugees.ie while also working fulltime with a major digital services company.</p>
<p>There have been positives for him such as being able to pursue his “passion for IT” and work in cloud technology.</p>
<p>Living here has also been challenging, particularly having to share a room in the centre where he lives and trying to do his job via mobile phone when the WIFI signal drops.</p>
<p>If he were to change anything about the current asylum system here, it would be to ensure that refugees and asylum seekers have access to “unlimited labour” opportunities and a driving licence.</p>
<blockquote><p><a href="https://changingireland.ie/first-specialist-recruitment-company-for-refugees-and-asylum-seekers/">First specialist recruitment company for refugees and asylum-seekers</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“First specialist recruitment company for refugees and asylum-seekers” — Changing Ireland" src="https://changingireland.ie/first-specialist-recruitment-company-for-refugees-and-asylum-seekers/embed/#?secret=UOep2uThcn#?secret=qr8Tsy1eaG" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Living here has been challenging, having to share a room in the centre where he lives and trying to do his job for Dropbox via mobile phone when the WIFI signal drops.', 'https://changingireland.ie/wp-content/uploads/2021/11/Photo-of-Andile.jpg', '', '[{"slug":"empowerment","title":"Empowerment"},{"slug":"income-employment","title":"Income & Employment"},{"slug":"uncategorized","title":"Uncategorized"}]', '[{"slug":"refugees","title":"refugees"}]', '', 251245, 1, '2021-11-04T10:45:57Z', '2021-11-04T10:51:14Z', '2021-11-04T10:45:57Z')
