INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Egyptian journalist free to practise again', 'egyptian-journalist-free-to-practise-again', '<p align="left"><span lang="EN-GB">Ahmed (*not his real name) is a sterling example of the incredible talent that newcomers to Ireland possess and that RecruitRefugees .ie is trying to promote. </span></p>
<p align="left"><span lang="EN-GB">An experienced journalist from Cairo whose photojournalism and documentary work has won awards, he has worked in 13 countries and for well-known media outlets such as Euronews and Associated Press. He has also covered protests in Egypt against the government. He tells me that his home country ranks 3rd in the world for the number of imprisoned journalists and 153rd in world rankings for press freedom. </span></p>
<p align="left"><span lang="EN-GB">Much of the appeal of Ireland is that he is now living in a country that ranks 8th or 9th in the world in terms of press freedom. As a former asylum seeker who now has leave to remain and work, life in Ireland is “really good. It is the ideal peaceful place that I need to live in for now, after what I have seen and what I have covered.” </span></p>
<p align="left"><span lang="EN-GB">The big difference for him being able to work and contribute is that he is “no longer afraid”. </span></p>
<p align="left"><span lang="EN-GB">“When I was in my country, you might be arrested, you might be deported because of your work. Here I am not afraid to write about whichever topic I want,” he said.</span></p>
<blockquote><p><a href="https://changingireland.ie/first-specialist-recruitment-company-for-refugees-and-asylum-seekers/">First specialist recruitment company for refugees and asylum-seekers</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“First specialist recruitment company for refugees and asylum-seekers” — Changing Ireland" src="https://changingireland.ie/first-specialist-recruitment-company-for-refugees-and-asylum-seekers/embed/#?secret=rfVNgC5J7e#?secret=E9Sx6BBumr" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Life in Ireland is “really good. It is the ideal peaceful place after what I have seen and what I have covered.”', 'https://changingireland.ie/wp-content/uploads/2021/11/Egypt_Censor_pic_4-800x500_c.jpg', '', '[{"slug":"empowerment","title":"Empowerment"},{"slug":"income-employment","title":"Income & Employment"},{"slug":"uncategorized","title":"Uncategorized"}]', '[{"slug":"refugees","title":"refugees"}]', '', 251246, 1, '2021-11-04T10:37:30Z', '2021-11-04T10:57:02Z', '2021-11-04T10:37:30Z')
