INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Practical tips for using humour with young people', 'practical-tips-for-using-humour-with-young-people', '<p align="left"><b><span lang="EN-GB">• Always be prepared to laugh at and make fun of yourself – young people appreciate an adult that is prepared to do this – they tend to think this person is ok!</span></b></p>
<p align="left"><span lang="EN-GB">• Always greet young people with a smile – it can set the tone for them and you!</span></p>
<p align="left"><b><span lang="EN-GB">• Make sure the humour you use is equal to the relationship you have with the person you are engaging with – they must understand where you are going with it and be ok with it.</span></b></p>
<p align="left"><span lang="EN-GB">• When you use humour, you are making it ok for others to use it, but it might not be the kind of humour you expect or respect, so prepare yourself – not how to react, but how to respond. Your response will be key, particularly for any young person that might not understand your boundaries or expectations.</span></p>
<p align="left"><b><span lang="EN-GB">• Don’t make young people the joke because you can and/or it’s easy for you.</span></b></p>
<p align="left"><span lang="EN-GB">• When young people try to use humour to belittle or put you down, ‘embrace’ and use it to your advantage. By taking ownership of their humour you can turn the situation around and create a new situation which leads to a better outcome.</span></p>
<p align="left"><b><span lang="EN-GB">• Don’t interpret every act of humour as an attempt to get at you – for some it’s a defence mechanism and is all they know.</span></b></p>
<p align="left"><span lang="EN-GB">• Be prepared to challenge certain kinds of humour if it crosses ethical boundaries &#8211; explain why you are challenging it and what the issue with it is.</span></p>
<p align="left"><b><span lang="EN-GB">• Help young people to explore humour and understand the implications of it if it is misused.</span></b></p>
<p align="left"><span lang="EN-GB">• Your humour should only be used to care for the person you’re trying to work with. It’s designed to lighten the moment, put a smile on their face and be enjoyed by them. It can offer perspectives they might not have thought about and is based around the relationship you already have with them.</span></p>
<h2 align="left">Contact Fergal</h2>
<p align="left"><strong>You can email Fergal Barr on: thekingisalive@hotmail.com</strong></p>
<blockquote><p><a href="https://changingireland.ie/the-one-art-form-missing-from-youthwork-is-humour/">The one art form missing from youthwork is humour</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“The one art form missing from youthwork is humour” — Changing Ireland" src="https://changingireland.ie/the-one-art-form-missing-from-youthwork-is-humour/embed/#?secret=JgH2svLv6k#?secret=VqukVRgrR6" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'By Fergal Barr', 'https://changingireland.ie/wp-content/uploads/2021/11/Fergal.jpg', '', '[{"slug":"opinion-advice","title":"OPINION/ADVICE"},{"slug":"people","title":"People"}]', '[{"slug":"department-children-youth-affairs-dcya","title":"Department of Children and Youth Affairs"},{"slug":"youth-work","title":"youth work"}]', '', 251282, 1, '2021-11-04T10:25:33Z', '2021-11-04T11:32:40Z', '2021-11-04T10:25:33Z')
